import React, { useState } from 'react';
import axios from 'axios';
import GraphBackground from './GraphBackground';

const Hero = () => {
  const [showScanner, setShowScanner] = useState(false);
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState(null);

  const triggerScanner = async () => {
    setShowScanner(true);
    setLoading(true);
    setResults(null); // Purana data clear karne ke liye

    try {
      // Backend api/start-scan ko call karna
      // Ensure kar ki tera Flask server port 5000 par chal raha hai
      const response = await axios.get('http://127.0.0.1:5000/api/start-scan');
      setResults(response.data);
    } catch (err) {
      console.error("Scanner Error:", err);
      setResults({ error: "Failed to connect to backend engine. Check Flask server." });
    }
    setLoading(false);
  };

  return (
    <div className="relative min-h-screen flex items-center justify-center bg-transparent">
      {/* Dynamic IP Graph Background */}
      <GraphBackground />

      <div className="relative z-10 text-center px-4">
        {/* Main Title Block with Glow */}
        <div className="flex flex-col items-center justify-center mb-16 px-4 relative">
          {/* Glow effect behind title */}
          <div className="absolute inset-0 -z-10 blur-3xl">
            <div className="absolute inset-0 bg-gradient-to-r from-cyan-500/20 via-transparent to-purple-500/20 rounded-full"></div>
          </div>
          
          <h1 className="text-4xl md:text-7xl lg:text-[7rem] font-black text-white uppercase tracking-tighter leading-[1.1] text-center drop-shadow-2xl max-w-screen-xl relative">
            NET_SCAN : <br className="hidden md:block" /><span className="text-gray-300 md:text-6xl lg:text-[5rem] tracking-tight bg-gradient-to-r from-cyan-300 via-blue-300 to-purple-300 bg-clip-text text-transparent">Graph-Intelligent Attack Path Analyzer</span>
          </h1>
        </div>

        <div className="flex gap-6 justify-center mt-10 md:mt-16 relative z-10">
          <button className="glass-btn px-10 py-3 rounded-full text-xs uppercase">
            INFORMATION
          </button>
          <button
            onClick={triggerScanner}
            className="glass-btn-primary px-10 py-3 rounded-full text-xs uppercase"
          >
            {loading ? "INITIALIZING..." : "VULNERABILITY"}
          </button>
        </div>

        {/* 🛠️ LIVE SCANNER TERMINAL WINDOW */}
        {showScanner && (
          <div className="fixed inset-x-0 bottom-0 h-1/3 glow-container backdrop-blur-xl z-50 animate-in slide-in-from-bottom duration-500 mx-4 mb-4">
            <div className="flex justify-between items-center mb-4 border-b border-neon-cyan/30 pb-2">
              <span className="text-neon-cyan font-mono text-xs font-bold tracking-widest uppercase">
                {loading ? ">>> RUNNING SECURITY ASSESSMENT..." : ">>> SCAN COMPLETED"}
              </span>
              <button
                onClick={() => setShowScanner(false)}
                className="glass-btn px-3 py-1 rounded-lg text-xs hover:scale-110 transition-transform"
              >
                CLOSE [X]
              </button>
            </div>

            <div className="font-mono text-[11px] text-neon-cyan/80 text-left overflow-y-auto h-full pb-10 custom-scrollbar p-4">
              {loading ? (
                <div className="animate-pulse">
                  [SYSTEM] Accessing network packets...<br />
                  [SYSTEM] Identifying critical attack paths...<br />
                  [SYSTEM] Fetching vulnerability data from main.py...
                </div>
              ) : (
                <pre className="whitespace-pre-wrap">
                  {results ? JSON.stringify(results, null, 2) : "No scan results found."}
                </pre>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Hero;